package com.mycompany.rentalmanagement.servlet;import com.mycompany.rentalmanagement.dao.CustomerDAO;import com.mycompany.rentalmanagement.util.ValidationUtil;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.IOException;
@WebServlet("/customers") public class CustomerServlet extends HttpServlet{CustomerDAO dao=new CustomerDAO();protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{if("edit".equals(r.getParameter("action"))){r.setAttribute("customer",dao.get(Long.parseLong(r.getParameter("id"))));r.getRequestDispatcher("/WEB-INF/views/customer-form.jsp").forward(r,s);return;}r.setAttribute("customers",dao.list(r.getParameter("q")));r.getRequestDispatcher("/WEB-INF/views/customers.jsp").forward(r,s);}catch(Exception e){r.setAttribute("error",e.getMessage());r.getRequestDispatcher("/WEB-INF/views/error.jsp").forward(r,s);}}protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{if("deactivate".equals(r.getParameter("action")))dao.deactivate(Long.parseLong(r.getParameter("id")));else{long id=r.getParameter("id")==null||r.getParameter("id").isBlank()?0:Long.parseLong(r.getParameter("id"));String name=ValidationUtil.text(r.getParameter("full_name"),"Name",120),phone=ValidationUtil.text(r.getParameter("phone"),"Phone",30),license=ValidationUtil.text(r.getParameter("license_number"),"License number",80);String email=r.getParameter("email")==null?"":r.getParameter("email").trim();if(!email.isBlank()&&!email.matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$"))throw new IllegalArgumentException("Enter a valid email address.");dao.save(id,name,email,phone,license,r.getParameter("address"));}s.sendRedirect(r.getContextPath()+"/customers?success=1");}catch(Exception e){r.setAttribute("error",e.getMessage());try{r.setAttribute("customers",dao.list(""));}catch(Exception ignored){}r.getRequestDispatcher("/WEB-INF/views/customers.jsp").forward(r,s);}}}
